import sys

def check_digisible(n):
    """Return (is_digisible, failure_reasons)"""
    s = str(n)
    reasons = []

    # Check zero
    if '0' in s:
        reasons.append("ZERO")

    # Check duplicate digits
    if len(set(s)) != len(s):
        reasons.append("DUPLICATE")

    # Check divisibility (only if no zero, because division by zero is impossible)
    if '0' not in s:
        for ch in s:
            if n % int(ch) != 0:
                reasons.append("DIVISIBLE")
                break

    is_dig = (len(reasons) == 0)
    return is_dig, "+".join(reasons) if reasons else ""

def next_digisible(start):
    """Find smallest digisible number >= start"""
    n = start
    while True:
        is_dig, _ = check_digisible(n)
        if is_dig:
            return n
        n += 1

def main():
    N = int(sys.stdin.readline().strip())

    is_dig, reasons = check_digisible(N)

    if is_dig:
        print(N)
    else:
        print(f"{reasons}")
        print(next_digisible(N))

if __name__ == "__main__":
    main()
